#!/usr/bin/env bash
# percona/pg-operator 3.0.0 - base variant: no-crds
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/percona-pg-operator-3-0-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the no-crds base variant into ./percona-pg-operator-3-0-0-no-crds"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/percona-pg-operator:3.0.0 --base no-crds --work-dir ./percona-pg-operator-3-0-0-no-crds --non-interactive --namespace default

say "Read what was rendered; nothing has touched the cluster yet"
ls ./percona-pg-operator-3-0-0-no-crds/out/manifests

say "Ensure the default namespace exists"
kubectl create namespace default --dry-run=client -o yaml | kubectl apply -f -

say "Check 8 CRDs included with this package"
missing_crds=0
if ! kubectl get crd/crunchybridgeclusters.upstream.pgv2.percona.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/perconapgbackups.pgv2.percona.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/perconapgclusters.pgv2.percona.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/perconapgrestores.pgv2.percona.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/perconapgupgrades.pgv2.percona.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/pgadmins.upstream.pgv2.percona.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/pgupgrades.upstream.pgv2.percona.com >/dev/null 2>&1; then
  missing_crds=1
fi
if ! kubectl get crd/postgresclusters.upstream.pgv2.percona.com >/dev/null 2>&1; then
  missing_crds=1
fi
if [ "$missing_crds" -eq 1 ]; then
  kubectl apply --server-side -f ./percona-pg-operator-3-0-0-no-crds/package/prerequisites/target-facts/no-crds-crds.yaml
else
  say "The required CRDs already exist; leave them under their current owner"
fi
kubectl wait --for=condition=Established --timeout=120s crd/crunchybridgeclusters.upstream.pgv2.percona.com
kubectl wait --for=condition=Established --timeout=120s crd/perconapgbackups.pgv2.percona.com
kubectl wait --for=condition=Established --timeout=120s crd/perconapgclusters.pgv2.percona.com
kubectl wait --for=condition=Established --timeout=120s crd/perconapgrestores.pgv2.percona.com
kubectl wait --for=condition=Established --timeout=120s crd/perconapgupgrades.pgv2.percona.com
kubectl wait --for=condition=Established --timeout=120s crd/pgadmins.upstream.pgv2.percona.com
kubectl wait --for=condition=Established --timeout=120s crd/pgupgrades.upstream.pgv2.percona.com
kubectl wait --for=condition=Established --timeout=120s crd/postgresclusters.upstream.pgv2.percona.com

if [ -d ./percona-pg-operator-3-0-0-no-crds/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./percona-pg-operator-3-0-0-no-crds/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./percona-pg-operator-3-0-0-no-crds/out/manifests

say "Done. The cluster received exactly the files in ./percona-pg-operator-3-0-0-no-crds/out."
